def pairs():
    yield 1, 2
    yield 3, 4
print(list(pairs()))
for a, b in pairs():
    print(a + b)

def c(n):
    i = 0
    while i < n:
        yield i
        i += 1
print([x for x in c(4)])
for v in c(3):
    print("v", v)

def bad():
    yield 1
    raise ValueError("gen")
g = bad()
print(next(g))
try:
    next(g)
except ValueError as e:
    print("gen err", e)
